WITH mesh_agg AS (
    SELECT zoneref, AVG(facetverts::numeric / NULLIF(facetfaces, 0)) as avg_mcr, AVG(texpix::numeric / 10) as avg_tdi, AVG(geomdeltamm) as avg_geomdelta FROM scanmesh GROUP BY zoneref
),
pointcloud_agg AS (
    SELECT sc.zoneref, AVG(p.coverpct) as avg_coverpct, AVG(p.lappct) as avg_lappct, AVG(p.scanresolmm) as avg_scanresol, AVG(p.noisedb) as avg_noisedb FROM scans sc JOIN scanpointcloud p ON sc.arcref = p.arcref GROUP BY sc.zoneref
),
reg_agg AS (
    SELECT sc.zoneref, AVG(r.logaccumm) as avg_logaccu, AVG(r.errvalmm) as avg_errval FROM scans sc JOIN scanregistration r ON sc.arcref = r.arcref GROUP BY sc.zoneref
),
scan_agg AS (
    SELECT zoneref, AVG(scancount::numeric) as avg_sqs FROM scans GROUP BY zoneref
),
combined AS (
    SELECT s.zoneregistry as site_code, s.zonelabel as site_designation, COALESCE(m.avg_mcr, 0) as mcr, COALESCE(m.avg_tdi, 0) as tdi, COALESCE(m.avg_geomdelta, 0) as geomdelta, COALESCE(pc.avg_coverpct, 0) as coverpct, COALESCE(pc.avg_lappct, 0) as lappct, COALESCE(pc.avg_scanresol, 0) as scanresol, COALESCE(pc.avg_noisedb, 0) as noisedb, COALESCE(r.avg_logaccu, 0) as logaccu, COALESCE(r.avg_errval, 0) as errval, COALESCE(sa.avg_sqs, 0) as sqs FROM sites s LEFT JOIN mesh_agg m ON s.zoneregistry = m.zoneref LEFT JOIN pointcloud_agg pc ON s.zoneregistry = pc.zoneref LEFT JOIN reg_agg r ON s.zoneregistry = r.zoneref LEFT JOIN scan_agg sa ON s.zoneregistry = sa.zoneref
)
SELECT site_code, site_designation, noisedb, scanresol, errval, sqs FROM combined WHERE sqs = 0 OR scanresol = 0 LIMIT 5;

