WITH mesh_data AS (
    SELECT zoneref, AVG(facetfaces::numeric / (NULLIF(facetverts, 0) * pow(facetresmm, 2))) * 1000 as mcr, AVG(texpix::numeric / (sqrt(NULLIF(facetfaces, 0)) * facetresmm)) * 0.01 as tdi, AVG(geomdeltamm) as geomdelta FROM scanmesh GROUP BY zoneref
),
pointcloud_data AS (
    SELECT sc.zoneref, AVG(p.coverpct) as coverpct, AVG(p.lappct) as lappct, AVG(p.scanresolmm) as scanresol, AVG(p.noisedb) as noisedb, AVG(p.pointdense::numeric) as pointdense FROM scans sc JOIN scanpointcloud p ON sc.arcref = p.arcref GROUP BY sc.zoneref
),
reg_data AS (
    SELECT sc.zoneref, AVG(r.logaccumm) as logaccu, AVG(r.errvalmm) as errval FROM scans sc JOIN scanregistration r ON sc.arcref = r.arcref GROUP BY sc.zoneref
),
combined AS (
    SELECT s.zoneregistry as site_code, s.zonelabel as site_designation, COALESCE(m.mcr, 0) as mcr, COALESCE(m.tdi, 0) as tdi, COALESCE(m.geomdelta, 0) as geomdelta, COALESCE(pc.coverpct, 0) as coverpct, COALESCE(pc.lappct, 0) as lappct, COALESCE(pc.scanresol, 0) as scanresol, COALESCE(pc.noisedb, 0) as noisedb, COALESCE(pc.pointdense, 0) as pointdense, COALESCE(r.logaccu, 0) as logaccu, COALESCE(r.errval, 0) as errval FROM sites s LEFT JOIN mesh_data m ON s.zoneregistry = m.zoneref LEFT JOIN pointcloud_data pc ON s.zoneregistry = pc.zoneref LEFT JOIN reg_data r ON s.zoneregistry = r.zoneref
),
step1 AS (
    SELECT *, CASE WHEN pointdense > 1 THEN ln(scanresol * 1000.0) / ln(pointdense) * 5 ELSE 0 END as sri, coverpct * (1 + (lappct / 100.0) * (1 - coverpct / 100.0)) as sce, mcr * (tdi / 10.0) * (1 + exp(-geomdelta)) as mfs, CASE WHEN logaccu > 0 THEN scanresol / (logaccu * sqrt(1 + errval / logaccu)) ELSE 0 END as rar FROM combined
),
step2 AS (
    SELECT *, CASE WHEN sri > 0 THEN power(10.0 / sri, 1.5) * (sce / 100.0) * power(1 - noisedb / 30.0, 2) ELSE 0 END as sqs FROM step1
),
step3 AS (
    SELECT *, (sqs * 0.4) + (mfs * 0.4) + (sce * 0.2) - 5 * sqrt(noisedb / 10.0) as adc, (0.3 * ((sqs * 0.4) + (mfs * 0.4) + (sce * 0.2) - 5 * sqrt(noisedb / 10.0))) + (0.3 * mfs) + (0.2 * rar) + (0.2 * sce) - 2 * sqrt(CASE WHEN errval > 0 AND scanresol > 0 THEN errval / scanresol ELSE 0 END) as dpq FROM step2
)
SELECT COUNT(*) FROM step3;

